import { Head, Form, router } from '@inertiajs/react';
import { FormEvent, useState } from 'react';

type Business = { id: number; restaurant_id?: number | null; name: string; city: string; area?: string | null; address?: string | null; category: string; phone?: string | null; website_url?: string | null; maps_url?: string | null; source_url?: string | null; menu_url?: string | null; menu_status: string; claim_status: string; listing_status: string; lead_status: string; confidence_score?: number | null; evidence_notes?: string | null; last_contacted_at?: string | null; next_action_at?: string | null; contact_channel?: string | null; menu_rights_status: string; internal_notes?: string | null; order_stats?: { orders_count: number; completed_orders: number; open_orders: number; paid_revenue: number }; demo_workspaces?: Array<{ id: number; status: string; expires_at: string; created_at: string; is_usable: boolean }>; demo_invitations?: Array<{ id: number; demo_workspace_id?: number | null; status: string; requested_mode?: string | null; style?: string | null; expires_at: string; submitted_at?: string | null; created_at: string }>; menu_researches?: MenuResearchRecord[]; activities?: Array<{ id: number; type: string; outcome?: string | null; channel?: string | null; notes?: string | null; occurred_at: string }> };
type Page<T> = { data: T[]; links: Array<{ url: string | null; label: string; active: boolean }>; total: number };
type DiscoveredPlace = { source_place_id: string; name: string; address?: string; maps_url?: string; website_url?: string; phone?: string; category?: string };
type RecentActivity = { id: number; business_id: number; business_name: string; city?: string; type: string; outcome?: string | null; channel?: string | null; notes?: string | null; actor?: string | null; occurred_at: string };
type RecentOrder = { id: number; restaurant_id: number; restaurant_name: string; order_number: string; customer_name: string; status: string; payment_status: string; total: number; created_at: string; history: Array<{ from_status?: string | null; to_status: string; actor?: string | null; created_at?: string | null }> };
type DemoResult = { workspace_id: number; invitation_id?: number | null; preview_url: string; owner_url: string; recommended_url?: string; expires_at: string; message: string };
type DemoInvitationResult = { invitation_id: number; request_url: string; expires_at: string; message: string };
type MenuCandidate = { url: string; label: string; kind: 'html' | 'image' | 'pdf'; host: string };
type ResearchItem = { name: string; price: number | null; description?: string | null; uncertain?: boolean };
type ResearchCategory = { name: string; items: ResearchItem[] };
type MenuResearchResult = { research_id: number; status: string; source_url: string; candidates: MenuCandidate[]; message: string; error_message?: string | null };
type MenuResearchRecord = { id: number; status: string; source_website_url: string; selected_menu_url?: string | null; discovered_links?: MenuCandidate[]; extracted_data?: { categories?: ResearchCategory[] } | null; reviewed_data?: { categories?: ResearchCategory[] } | null; error_message?: string | null; discovered_at?: string | null; processed_at?: string | null; reviewed_at?: string | null; created_at?: string | null };
const menuLabels: Record<string, string> = { unknown: 'غير معروف', available: 'المنيو موجود', missing: 'محتاجين المنيو', needs_review: 'محتاج مراجعة' };
const listingLabels: Record<string, string> = { draft: 'مسودة', published: 'منشور', archived: 'مؤرشف' };
const leadLabels: Record<string, string> = { needs_verification: 'محتاج تحقق', verified: 'تم التحقق', contacted: 'تم التواصل', interested: 'مهتم', demo_booked: 'تم حجز ديمو', proposal_sent: 'تم إرسال عرض', partner: 'شريك فعّال', not_interested: 'غير مهتم' };
const contactLabels: Record<string, string> = { phone: 'مكالمة', whatsapp: 'واتساب', facebook: 'فيسبوك', instagram: 'إنستجرام', in_person: 'زيارة مباشرة', email: 'بريد إلكتروني' };
const activityLabels: Record<string, string> = { call: 'مكالمة', message: 'رسالة', visit: 'زيارة', demo: 'ديمو', proposal: 'عرض سعر', note: 'ملاحظة', order_status: 'تغيير حالة طلب', payment_status: 'تغيير حالة دفع' };
const outcomeLabels: Record<string, string> = { no_answer: 'لم يرد', follow_up: 'متابعة لاحقة', interested: 'مهتم', not_interested: 'غير مهتم', demo_booked: 'حجز ديمو', proposal_sent: 'إرسال عرض', partner: 'أصبح شريكًا', new: 'جديد', confirmed: 'تم التأكيد', preparing: 'قيد التحضير', ready: 'جاهز', completed: 'مكتمل', cancelled: 'ملغي', unpaid: 'غير مدفوع', paid: 'مدفوع', refunded: 'مسترد' };
const orderStatusLabels: Record<string, string> = { new: 'جديد', confirmed: 'تم التأكيد', preparing: 'قيد التحضير', ready: 'جاهز', completed: 'مكتمل', cancelled: 'ملغي' };
const paymentStatusLabels: Record<string, string> = { unpaid: 'غير مدفوع', paid: 'مدفوع', refunded: 'مسترد' };
const formatDate = (value?: string | null) => value ? new Intl.DateTimeFormat('ar-EG', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value)) : '—';
const formatMoney = (value: number) => new Intl.NumberFormat('ar-EG', { style: 'currency', currency: 'EGP', maximumFractionDigits: 0 }).format(value);
const copyText = async (value: string) => { try { await navigator.clipboard.writeText(value); window.alert('تم النسخ. لم يتم إرسال أي رسالة تلقائيًا.'); } catch { window.alert(value); } };
const firstContactMessage = (business: Pick<Business, 'name' | 'city' | 'category'>) => `أهلًا بحضرتك، أنا من فريق NEXORA 👋\n\nإحنا بنجهّز للمطاعم تجربة منيو رقمي باسم وهوية المطعم، بحيث العميل يتصفح الأصناف والأسعار بسهولة، وصاحب المطعم يقدر يدير المنيو ويتابع الطلبات من لوحة واحدة.\n\nبدل ما أبعت لحضرتك صور أو كلام عام، نقدر نجهّز معاينة مخصصة لـ${business.name} تشوفها من الموبايل وتجرب رحلة العميل ولوحة الإدارة بنفسك. أي أصناف أو أسعار غير مؤكدة هنعلّمها للمراجعة، ومش هننشر أي حاجة من غير موافقتكم.\n\nيناسب حضرتك أبعتلك المعاينة هنا؟`;

export default function Scout({ businesses, filters, stats, provider, recentOrders = [], recentActivities = [] }: { businesses: Page<Business>; filters: Record<string, string>; stats: { all: number; draft: number; needs_menu: number; published: number; contacted?: number; partners?: number; followups_due?: number }; provider: { name: string; configured: boolean; enabled: boolean }; recentOrders?: RecentOrder[]; recentActivities?: RecentActivity[] }) {
    const [showForm, setShowForm] = useState(false);
    const [discoverQuery, setDiscoverQuery] = useState('مطاعم وكافيهات');
    const [discoverCity, setDiscoverCity] = useState('الزرقا');
    const [discovering, setDiscovering] = useState(false);
    const [discoverMessage, setDiscoverMessage] = useState('');
    const [discoveredPlaces, setDiscoveredPlaces] = useState<DiscoveredPlace[]>([]);
    const [intakingPlaceId, setIntakingPlaceId] = useState<string | null>(null);
    const [q, setQ] = useState(filters.q || '');
    const [city, setCity] = useState(filters.city || '');
    const [menuStatus, setMenuStatus] = useState(filters.menu_status || '');
    const [leadStatus, setLeadStatus] = useState(filters.lead_status || '');
    const [demoBusinessId, setDemoBusinessId] = useState('');
    const [demoStyle, setDemoStyle] = useState('modern');
    const [demoRequestNote, setDemoRequestNote] = useState('');
    const [demoResult, setDemoResult] = useState<DemoResult | null>(null);
    const [demoBusy, setDemoBusy] = useState(false);
    const [demoError, setDemoError] = useState('');
    const [invitationResult, setInvitationResult] = useState<DemoInvitationResult | null>(null);
    const [invitationBusy, setInvitationBusy] = useState(false);
    const [invitationError, setInvitationError] = useState('');
    const [menuResearchBusy, setMenuResearchBusy] = useState(false);
    const [menuResearch, setMenuResearch] = useState<MenuResearchResult | null>(null);
    const [menuResearchError, setMenuResearchError] = useState('');
    const [menuResearchMessage, setMenuResearchMessage] = useState('');
    const [menuCategories, setMenuCategories] = useState<ResearchCategory[]>([]);
    const [revokingWorkspaceId, setRevokingWorkspaceId] = useState<number | null>(null);
    const restoreLatestResearch = (businessId: string) => {
        const business = businesses.data.find(item => item.id === Number(businessId));
        const latest = business?.menu_researches?.[0];
        setMenuResearchError('');
        if (!latest) {
            setMenuResearch(null); setMenuCategories([]); setMenuResearchMessage('');
            return;
        }
        const rawCategories = latest.reviewed_data?.categories ?? latest.extracted_data?.categories ?? [];
        setMenuResearch({
            research_id: latest.id,
            status: latest.status,
            source_url: latest.selected_menu_url || latest.source_website_url,
            candidates: latest.discovered_links ?? [],
            message: latest.error_message || '',
            error_message: latest.error_message,
        });
        setMenuCategories(rawCategories.map((category: ResearchCategory) => ({
            name: category.name || '',
            items: (category.items || []).map(item => ({
                name: item.name || '',
                price: item.price == null || item.uncertain ? null : Number(item.price),
                description: item.description || '',
                uncertain: Boolean(item.uncertain),
            })),
        })));
        setMenuResearchMessage(`استعدنا آخر بحث محفوظ (#${latest.id}) بحالة: ${latest.status}. ${latest.error_message || ''}`);
    };
    const createDemo = async (event: FormEvent) => {
        event.preventDefault();
        if (!demoBusinessId || demoBusy) return;
        setDemoBusy(true); setDemoError(''); setDemoResult(null);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/businesses/${demoBusinessId}/demo`, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' },
                body: JSON.stringify({ style: demoStyle, request_note: demoRequestNote }),
            });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || Object.values(result.errors ?? {}).flat().join(' ') || 'تعذر إنشاء المعاينة.');
            setDemoResult(result as DemoResult);
        } catch (cause) { setDemoError(cause instanceof Error ? cause.message : 'حصل خطأ أثناء تجهيز المعاينة.'); }
        finally { setDemoBusy(false); }
    };
    const createInvitation = async () => {
        if (!demoBusinessId || invitationBusy) return;
        setInvitationBusy(true); setInvitationError(''); setInvitationResult(null);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/businesses/${demoBusinessId}/demo-invitations`, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' },
                body: JSON.stringify({}),
            });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || Object.values(result.errors ?? {}).flat().join(' ') || 'تعذر إنشاء رابط الاختيار.');
            setInvitationResult(result as DemoInvitationResult);
            router.reload({ only: ['businesses', 'recentActivities'] });
        } catch (cause) { setInvitationError(cause instanceof Error ? cause.message : 'حصل خطأ أثناء إنشاء رابط الاختيار.'); }
        finally { setInvitationBusy(false); }
    };
    const discoverOfficialMenu = async () => {
        if (!demoBusinessId || menuResearchBusy) return;
        const business = businesses.data.find(item => item.id === Number(demoBusinessId));
        if (!business?.website_url) { setMenuResearchError('أضف رابط الموقع الرسمي للمطعم أولًا، وتأكد إنه الموقع الصحيح.'); return; }
        setMenuResearchBusy(true); setMenuResearchError(''); setMenuResearchMessage('جاري فحص الموقع الرسمي والبحث عن روابط المنيو...');
        setMenuResearch(null); setMenuCategories([]);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/businesses/${business.id}/menu-research`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' } });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || 'تعذر البحث عن المنيو.');
            setMenuResearch(result as MenuResearchResult); setMenuResearchMessage(result.message || 'تم العثور على روابط مرشحة.');
        } catch (cause) { setMenuResearchError(cause instanceof Error ? cause.message : 'حدث خطأ أثناء البحث.'); setMenuResearchMessage(''); }
        finally { setMenuResearchBusy(false); }
    };
    const intakeDiscoveredPlace = async (place: DiscoveredPlace) => {
        if (!place.website_url || intakingPlaceId) return;
        if (!window.confirm('هل راجعت الرابط وده فعلًا الموقع الرسمي للمطعم؟ هنحفظ معرّف المكان ورابط الموقع، ونستخرج اسم المطعم من موقعه الرسمي. لن نحفظ اسم/عنوان/هاتف Google ولن يتم أي تواصل أو نشر.')) return;
        setIntakingPlaceId(place.source_place_id); setDiscoverMessage('جاري فحص الموقع الرسمي واكتشاف روابط المنيو...');
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch('/local-scout/official-site-intake', {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' },
                body: JSON.stringify({ source_place_id: place.source_place_id, website_url: place.website_url, city: discoverCity }),
            });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || 'تعذر إضافة المطعم من مصدره الرسمي.');
            setDemoBusinessId(String(result.business_id));
            setMenuResearch({ research_id: result.research_id, status: result.status, source_url: result.source_url, candidates: result.candidates || [], message: result.message });
            setMenuCategories([]); setMenuResearchError(''); setMenuResearchMessage(result.message || 'تم إنشاء سجل خاص واكتشاف روابط المنيو.');
            setDiscoverMessage(`تم تجهيز سجل ${result.business_name} (#${result.business_id}). ${result.message || ''}`);
            setDiscoveredPlaces(current => current.filter(item => item.source_place_id !== place.source_place_id));
            router.reload({ only: ['businesses', 'stats', 'recentActivities'] });
            window.setTimeout(() => document.getElementById('menu-research-panel')?.scrollIntoView({ behavior: 'smooth', block: 'start' }), 150);
        } catch (cause) {
            setDiscoverMessage(cause instanceof Error ? cause.message : 'حدث خطأ أثناء إضافة المطعم.');
        } finally { setIntakingPlaceId(null); }
    };
    const extractMenuCandidate = async (candidate: MenuCandidate) => {
        if (!menuResearch || menuResearchBusy) return;
        setMenuResearchBusy(true); setMenuResearchError(''); setMenuResearchMessage('جاري تحميل الرابط المختار واستخراج الأصناف والأسعار...'); setMenuCategories([]);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/menu-research/${menuResearch.research_id}/extract`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ candidate_url: candidate.url }) });
            const result = await response.json().catch(() => ({}));
            if (result.status) setMenuResearch(previous => previous ? { ...previous, status: result.status } : previous);
            if (!response.ok) throw new Error(result.message || 'تعذر استخراج الأصناف.');
            setMenuCategories((result.categories || []).map((category: ResearchCategory) => ({ name: category.name || '', items: (category.items || []).map(item => ({ name: item.name || '', price: item.price == null || item.uncertain ? null : Number(item.price), description: item.description || '', uncertain: Boolean(item.uncertain) })) })));
            setMenuResearchMessage(result.message || 'راجع أسماء الأصناف والأسعار قبل الحفظ.');
        } catch (cause) { setMenuResearchError(cause instanceof Error ? cause.message : 'حدث خطأ أثناء استخراج المنيو.'); setMenuResearchMessage(''); }
        finally { setMenuResearchBusy(false); }
    };
    const saveMenuReview = async () => {
        if (!menuResearch || menuResearchBusy || !menuCategories.length) return;
        setMenuResearchBusy(true); setMenuResearchError(''); setMenuResearchMessage('جاري حفظ المسودة التي راجعتها...');
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/menu-research/${menuResearch.research_id}/review`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ categories: menuCategories }) });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || Object.values(result.errors ?? {}).flat().join(' ') || 'تعذر حفظ المراجعة.');
            setMenuResearch(previous => previous ? { ...previous, status: 'reviewed' } : previous);
            setMenuResearchMessage(`${result.message} عدد الأصناف: ${result.items_count}.`);
        } catch (cause) { setMenuResearchError(cause instanceof Error ? cause.message : 'حدث خطأ أثناء حفظ المراجعة.'); setMenuResearchMessage(''); }
        finally { setMenuResearchBusy(false); }
    };
    const createDemoFromMenu = async () => {
        if (!demoBusinessId || !menuResearch || menuResearch.status !== 'reviewed' || demoBusy) return;
        setDemoBusy(true); setDemoError(''); setDemoResult(null);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/businesses/${demoBusinessId}/demo`, { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' }, body: JSON.stringify({ style: demoStyle, request_note: demoRequestNote, menu_research_id: menuResearch.research_id }) });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || Object.values(result.errors ?? {}).flat().join(' ') || 'تعذر إنشاء معاينة المنيو.');
            setDemoResult(result as DemoResult); setMenuResearch(previous => previous ? { ...previous, status: 'demo_ready' } : previous);
            router.reload({ only: ['businesses', 'recentActivities'] }); window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (cause) { setDemoError(cause instanceof Error ? cause.message : 'حدث خطأ أثناء تجهيز المعاينة.'); }
        finally { setDemoBusy(false); }
    };
    const provisionDemoForInvitation = async (business: Business, invitationId: number) => {
        if (demoBusy) return;
        setDemoBusy(true); setDemoError(''); setDemoResult(null);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/businesses/${business.id}/demo`, {
                method: 'POST', credentials: 'same-origin',
                headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}), 'X-Requested-With': 'XMLHttpRequest' },
                body: JSON.stringify({ invitation_id: invitationId }),
            });
            const result = await response.json().catch(() => ({}));
            if (!response.ok) throw new Error(result.message || Object.values(result.errors ?? {}).flat().join(' ') || 'تعذر تجهيز Demo للطلب.');
            setDemoResult(result as DemoResult);
            router.reload({ only: ['businesses', 'recentActivities'] });
            window.scrollTo({ top: 0, behavior: 'smooth' });
        } catch (cause) { setDemoError(cause instanceof Error ? cause.message : 'حصل خطأ أثناء تجهيز Demo للطلب.'); }
        finally { setDemoBusy(false); }
    };
    const revokeInvitation = async (invitationId: number) => {
        if (!window.confirm('إيقاف رابط الاختيار ده؟ مش هيقبل طلبات جديدة بعد الإيقاف.')) return;
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/demo-invitations/${invitationId}/revoke`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}) } });
            if (!response.ok) throw new Error('تعذر إيقاف رابط الاختيار.');
            router.reload({ only: ['businesses'] });
        } catch (cause) { window.alert(cause instanceof Error ? cause.message : 'حصل خطأ أثناء إيقاف الرابط.'); }
    };
    const copyDemoMessage = async () => {
        if (!demoResult) return;
        const text = `${demoResult.message}\n\nرابط التجربة المناسبة لطلب العميل: ${demoResult.recommended_url || demoResult.preview_url}`;
        try { await navigator.clipboard.writeText(text); window.alert('اتنسخت الرسالة ومعاها الرابط المناسب لاختيار العميل. لم يتم إرسال أي رسالة تلقائيًا.'); }
        catch { window.alert(text); }
    };
    const revokeDemo = async () => {
        if (!demoResult || !window.confirm('إيقاف المعاينة نهائيًا؟ الروابط الحالية ستتوقف عن العمل.')) return;
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/demos/${demoResult.workspace_id}/revoke`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}) } });
            if (!response.ok) throw new Error('تعذر إيقاف الرابط.');
            setDemoResult(null); window.alert('تم إيقاف رابطَي المعاينة.');
        } catch (cause) { window.alert(cause instanceof Error ? cause.message : 'حصل خطأ.'); }
    };
    const revokeWorkspace = async (workspaceId: number) => {
        if (!window.confirm('إيقاف روابط المعاينة دي؟ أي حد يستخدمها بعد كده مش هيقدر يدخل.')) return;
        setRevokingWorkspaceId(workspaceId);
        try {
            const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content;
            const response = await fetch(`/local-scout/demos/${workspaceId}/revoke`, { method: 'POST', credentials: 'same-origin', headers: { Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}) } });
            if (!response.ok) throw new Error('تعذر إيقاف رابط المعاينة.');
            router.reload({ only: ['businesses'] });
        } catch (cause) { window.alert(cause instanceof Error ? cause.message : 'حصل خطأ أثناء إيقاف المعاينة.'); }
        finally { setRevokingWorkspaceId(null); }
    };
    return <main dir="rtl" className="min-h-screen bg-slate-50 text-slate-950"><Head title="NEXORA Scout" /><header className="bg-slate-950 text-white"><div className="mx-auto flex max-w-7xl items-center justify-between px-4 py-5"><div><p className="text-xs font-bold tracking-widest text-emerald-300">NEXORA LOCAL</p><h1 className="mt-1 text-2xl font-black">Scout · اكتشاف المطاعم</h1></div><a href="/local" className="rounded-xl border border-white/20 px-4 py-2 text-sm font-bold">عرض الدليل العام</a></div></header>
        <div className="mx-auto max-w-7xl px-4 py-7"><section className="grid gap-3 sm:grid-cols-2 lg:grid-cols-3">{[['كل المطاعم', stats.all], ['مسودات', stats.draft], ['تحتاج منيو أو مراجعة', stats.needs_menu], ['منشور في الدليل', stats.published], ['عملاء تم التواصل معهم', stats.contacted ?? 0], ['شركاء فعّالون', stats.partners ?? 0], ['متابعات مستحقة', stats.followups_due ?? 0]].map(([label, value]) => <div key={label} className="rounded-2xl border border-slate-200 bg-white p-5"><p className="text-sm text-slate-500">{label}</p><p className="mt-2 text-3xl font-black">{value}</p></div>)}</section>
            <section className="mt-5 rounded-2xl border border-emerald-200 bg-white p-5">
                <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="text-xs font-black tracking-widest text-emerald-800">DEMO WORKSPACE</p><h2 className="mt-1 text-xl font-black">جهّز معاينة حقيقية من سجل العميل</h2><p className="mt-1 text-sm leading-6 text-slate-500">هننشئ رابط عميل ورابط صاحب المطعم بصلاحيات منفصلة، مع طلبات تجريبية لا تدخل الطلبات أو التقارير الحقيقية. صلاحية الرابط 7 أيام.</p></div><span className="h-fit rounded-full bg-emerald-50 px-3 py-2 text-xs font-bold text-emerald-800">خاص · قابل للإيقاف</span></div>
                <form onSubmit={createDemo} className="mt-4 grid gap-3 md:grid-cols-[1.4fr_180px_1fr_auto_auto] md:items-end"><label className="text-sm font-bold">سجل المطعم<select value={demoBusinessId} onChange={e => { setDemoBusinessId(e.target.value); setMenuResearch(null); setMenuCategories([]); setMenuResearchError(''); setMenuResearchMessage(''); }} required className="mt-1 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 font-normal"><option value="">اختار عميلًا من السجلات الحالية</option>{businesses.data.map(b => <option key={b.id} value={b.id}>{b.name} · {b.city}</option>)}</select></label><label className="text-sm font-bold">ستايل المعاينة<select value={demoStyle} onChange={e => setDemoStyle(e.target.value)} className="mt-1 w-full rounded-xl border border-slate-200 bg-white px-3 py-3 font-normal"><option value="modern">Modern</option><option value="playful">مبهج</option><option value="luxury">Premium</option><option value="classic">كلاسيك</option></select></label><label className="text-sm font-bold">ملاحظات طلب المعاينة<textarea value={demoRequestNote} onChange={e => setDemoRequestNote(e.target.value)} maxLength={1500} rows={1} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="ألوان البراند، صور معتمدة، ملاحظات خاصة..." /></label><button disabled={demoBusy || !demoBusinessId} className="rounded-xl bg-slate-950 px-5 py-3 font-bold text-white disabled:opacity-40">{demoBusy ? 'جاري الإنشاء...' : 'إنشاء Demo داخلي'}</button><button type="button" onClick={createInvitation} disabled={invitationBusy || !demoBusinessId} className="rounded-xl bg-emerald-800 px-5 py-3 font-bold text-white disabled:opacity-40">{invitationBusy ? 'جاري إنشاء الرابط...' : 'رابط اختيار للعميل'}</button></form>
                {invitationError && <p role="alert" className="mt-3 rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{invitationError}</p>}
                {invitationResult && <div className="mt-4 rounded-2xl border border-emerald-200 bg-emerald-50 p-4"><h3 className="font-black">رابط اختيار التجربة جاهز — لم يتم إرساله</h3><p className="mt-1 text-sm leading-6 text-emerald-950">{invitationResult.message}</p><p className="mt-2 break-all text-xs text-slate-600">{invitationResult.request_url}</p><p className="mt-2 text-xs text-slate-600">ينتهي: {formatDate(invitationResult.expires_at)}</p><div className="mt-3 flex flex-wrap gap-2"><a href={invitationResult.request_url} target="_blank" rel="noreferrer" className="rounded-lg bg-emerald-800 px-3 py-2 text-sm font-bold text-white">فتح صفحة الاختيار</a><button type="button" onClick={() => copyText(`${invitationResult.message}\n\n${invitationResult.request_url}`)} className="rounded-lg border border-emerald-300 bg-white px-3 py-2 text-sm font-bold">نسخ الرسالة والرابط</button></div></div>}
                {demoError && <p role="alert" className="mt-3 rounded-xl bg-rose-50 p-3 text-sm text-rose-800">{demoError}</p>}
                {demoResult && <div className="mt-5 rounded-2xl border border-slate-200 bg-slate-50 p-4"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-center"><div><h3 className="font-black">المعاينة جاهزة — لم يتم إرسالها</h3><p className="mt-1 text-xs text-slate-500">تنتهي الصلاحية: {formatDate(demoResult.expires_at)} · تم تسجيل الإنشاء في نشاط العميل دون تغيير مرحلة التواصل.</p></div><button onClick={revokeDemo} type="button" className="rounded-lg border border-rose-200 bg-white px-3 py-2 text-sm font-bold text-rose-700">إيقاف الروابط</button></div><div className="mt-4 grid gap-3 md:grid-cols-2"><div className="rounded-xl border border-slate-200 bg-white p-4"><p className="font-bold">رابط تجربة العميل</p><p className="mt-1 break-all text-xs text-slate-500">{demoResult.preview_url}</p><div className="mt-3 flex flex-wrap gap-2"><a href={demoResult.preview_url} target="_blank" rel="noreferrer" className="rounded-lg bg-emerald-800 px-3 py-2 text-sm font-bold text-white">فتح المعاينة</a><button type="button" onClick={() => copyText(demoResult.preview_url)} className="rounded-lg border px-3 py-2 text-sm font-bold">نسخ الرابط</button></div></div><div className="rounded-xl border border-slate-200 bg-white p-4"><p className="font-bold">رابط صاحب المطعم</p><p className="mt-1 break-all text-xs text-slate-500">{demoResult.owner_url}</p><div className="mt-3 flex flex-wrap gap-2"><a href={demoResult.owner_url} target="_blank" rel="noreferrer" className="rounded-lg bg-slate-950 px-3 py-2 text-sm font-bold text-white">فتح لوحة المعاينة</a><button type="button" onClick={() => copyText(demoResult.owner_url)} className="rounded-lg border px-3 py-2 text-sm font-bold">نسخ الرابط</button></div></div></div><div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={copyDemoMessage} className="rounded-lg border border-emerald-300 bg-emerald-50 px-4 py-3 text-sm font-bold text-emerald-900">نسخ الرسالة + الرابط المناسب لاختيار العميل</button><button type="button" onClick={() => copyText(`${demoResult.message}\n\nرابط العميل: ${demoResult.preview_url}\nرابط صاحب المطعم: ${demoResult.owner_url}`)} className="rounded-lg border px-4 py-3 text-sm font-bold">نسخ ملخص الرابطين داخليًا</button></div></div>}
            </section>
            <section className="mt-5 rounded-2xl border border-indigo-200 bg-white p-5">
                <div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-start"><div><p className="text-xs font-black tracking-widest text-indigo-700">MENU RESEARCH</p><h2 className="mt-1 text-xl font-black">من الموقع الرسمي إلى Demo جاهز</h2><p className="mt-1 max-w-3xl text-sm leading-6 text-slate-600">اختار سجل مطعم له موقع رسمي موثّق. هنفحص الموقع وقواعد robots.txt، ونكتشف روابط المنيو على نفس النطاق فقط، ثم نستخرج مسودة للمراجعة. لا نشر ولا تواصل تلقائي.</p></div><span className="h-fit rounded-full bg-indigo-50 px-3 py-2 text-xs font-bold text-indigo-800">مسودة خاصة · موافقة بشرية</span></div>
                <div className="mt-4 flex flex-wrap items-center gap-2"><button type="button" onClick={discoverOfficialMenu} disabled={!demoBusinessId || menuResearchBusy} className="rounded-xl bg-indigo-700 px-5 py-3 text-sm font-bold text-white disabled:opacity-40">{menuResearchBusy ? 'جاري الفحص...' : 'ابحث عن المنيو في الموقع الرسمي'}</button><span className="text-xs text-slate-500">يستخدم رابط الموقع المحفوظ في سجل المطعم؛ لا يبحث في مواقع غير مرتبطة به.</span></div>
                <div className="mt-3 flex flex-wrap gap-2"><button type="button" onClick={() => restoreLatestResearch(demoBusinessId)} disabled={!demoBusinessId || menuResearchBusy} className="rounded-xl border border-indigo-200 bg-white px-4 py-2 text-sm font-bold text-indigo-800 disabled:opacity-40">استرجاع آخر بحث محفوظ للمطعم</button><span className="self-center text-xs text-slate-500">يستعيد المسودة بعد إعادة تحميل الصفحة.</span></div>
                {menuResearchMessage && <p role="status" className="mt-3 rounded-xl bg-slate-50 p-3 text-sm leading-6">{menuResearchMessage}</p>}
                {menuResearchError && <p role="alert" className="mt-3 rounded-xl bg-rose-50 p-3 text-sm leading-6 text-rose-800">{menuResearchError}</p>}
                {menuResearch && <div className="mt-4 rounded-xl border border-slate-200 p-4"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-center"><div><h3 className="font-black">مصادر مرشحة للمنيو · بحث #{menuResearch.research_id}</h3><a className="mt-1 block break-all text-xs text-indigo-700 underline" href={menuResearch.source_url} target="_blank" rel="noreferrer">{menuResearch.source_url}</a></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{menuResearch.candidates.length} رابط</span></div>
                    {menuResearch.candidates.length === 0 ? <p className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-900">لم يتم العثور على رابط واضح للمنيو. راجع الموقع الرسمي أو أضف رابط المنيو يدويًا من بيانات المطعم.</p> : <div className="mt-3 space-y-2">{menuResearch.candidates.map(candidate => <article key={candidate.url} className="flex flex-col justify-between gap-3 rounded-xl bg-slate-50 p-3 sm:flex-row sm:items-center"><div className="min-w-0"><p className="font-bold">{candidate.label || 'رابط منيو مرشح'}</p><p className="mt-1 break-all text-xs text-slate-500">{candidate.url}</p><span className="mt-1 inline-block rounded-full bg-white px-2 py-1 text-[11px] text-slate-600">{candidate.kind === 'pdf' ? 'PDF — يحتاج رفعًا يدويًا كصور' : candidate.kind === 'image' ? 'صورة من الموقع' : 'صفحة ويب'}</span></div><div className="flex shrink-0 flex-wrap gap-2"><a href={candidate.url} target="_blank" rel="noreferrer" className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold">معاينة المصدر</a><button type="button" disabled={menuResearchBusy || candidate.kind === 'pdf'} onClick={() => extractMenuCandidate(candidate)} className="rounded-lg bg-indigo-700 px-3 py-2 text-xs font-bold text-white disabled:opacity-40">{candidate.kind === 'pdf' ? 'ارفع صفحات PDF يدويًا' : 'استخراج الأصناف والأسعار'}</button></div></article>)}</div>}
                </div>}
                {menuCategories.length > 0 && <div className="mt-5 rounded-xl border border-emerald-200 p-4"><div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-start"><div><h3 className="font-black">مراجعة الأصناف والأسعار</h3><p className="mt-1 text-sm text-slate-600">راجع كل صنف. السعر غير المقروء يظهر فارغًا ويجب تصحيحه قبل الحفظ. البيانات تظل مسودة خاصة.</p></div><span className="rounded-full bg-emerald-50 px-3 py-1 text-xs font-bold text-emerald-800">{menuCategories.reduce((sum, category) => sum + category.items.length, 0)} صنف</span></div>
                    <div className="mt-4 space-y-4">{menuCategories.map((category, categoryIndex) => <section key={`category-${categoryIndex}`} className="rounded-xl bg-slate-50 p-3"><label className="block text-sm font-bold">التصنيف<input value={category.name} onChange={e => setMenuCategories(current => current.map((entry, index) => index === categoryIndex ? { ...entry, name: e.target.value } : entry))} className="mt-1 w-full rounded-lg border border-slate-200 bg-white px-3 py-2 font-normal" /></label><div className="mt-3 space-y-2">{category.items.map((item, itemIndex) => <div key={`item-${categoryIndex}-${itemIndex}`} className="grid gap-2 rounded-lg border border-slate-200 bg-white p-3 sm:grid-cols-[1fr_140px]"><label className="text-xs font-bold">اسم الصنف<input value={item.name} onChange={e => setMenuCategories(current => current.map((entry, ci) => ci === categoryIndex ? { ...entry, items: entry.items.map((row, ii) => ii === itemIndex ? { ...row, name: e.target.value } : row) } : entry))} className="mt-1 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm font-normal" />{item.uncertain && <span className="mt-1 inline-block text-amber-700">راجع الاسم المستخرج</span>}</label><label className="text-xs font-bold">السعر بالجنيه<input type="number" min="0" step="0.01" value={item.price ?? ''} onChange={e => setMenuCategories(current => current.map((entry, ci) => ci === categoryIndex ? { ...entry, items: entry.items.map((row, ii) => ii === itemIndex ? { ...row, price: e.target.value === '' ? null : Number(e.target.value), uncertain: false } : row) } : entry))} placeholder="أكد السعر" className="mt-1 w-full rounded-lg border border-slate-200 px-3 py-2 text-sm font-normal" /></label>{item.description && <p className="text-xs leading-5 text-slate-500 sm:col-span-2">وصف مستخرج: {item.description}</p>}</div>)}</div></section>)}</div>
                    {menuResearchError && <p role="alert" className="mt-3 text-sm text-rose-800">{menuResearchError}</p>}
                    <div className="mt-4 flex flex-wrap gap-2"><button type="button" onClick={saveMenuReview} disabled={menuResearchBusy || menuResearch?.status === 'demo_ready' || menuCategories.some(category => !category.name.trim() || category.items.some(item => !item.name.trim() || item.price === null || !Number.isFinite(item.price) || item.price < 0))} className="rounded-xl bg-emerald-800 px-4 py-3 text-sm font-bold text-white disabled:opacity-40">{menuResearchBusy ? 'جاري الحفظ...' : 'اعتماد المراجعة البشرية'}</button>{menuResearch?.status === 'reviewed' && <button type="button" onClick={createDemoFromMenu} disabled={demoBusy} className="rounded-xl bg-slate-950 px-4 py-3 text-sm font-bold text-white disabled:opacity-40">{demoBusy ? 'جاري تجهيز Demo...' : 'جهّز Demo من المنيو ده'}</button>}</div>
                </div>}
                {menuResearch?.status === 'awaiting_ai_config' && <p className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-900">اكتشفنا رابط المنيو، لكن استخراج الـAI متوقف لأن OPENAI_API_KEY غير مضبوط في البيئة. بعد إعداد المفتاح، أعد محاولة استخراج رابط المنيو.</p>}
                {menuResearch?.status === 'manual_required' && <p className="mt-3 rounded-lg bg-amber-50 p-3 text-sm text-amber-900">المنيو ملف PDF؛ ارفع صفحاته كصور من أداة مسح المنيو الحالية ثم راجع النتائج. لن نخمن الأصناف أو الأسعار.</p>}
            </section>
            <section className="mt-5 rounded-2xl border border-slate-200 bg-white p-5">
                <div className="flex flex-col justify-between gap-2 sm:flex-row sm:items-end"><div><h2 className="text-lg font-black">معاينات مرتبطة بسجلات العملاء</h2><p className="mt-1 text-sm text-slate-500">آخر 3 معاينات لكل عميل في الصفحة الحالية. التوكنات لا تُعرض أو تُسترجع من قاعدة البيانات؛ احتفظ بالروابط عند إنشائها.</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{businesses.data.reduce((sum, b) => sum + (b.demo_workspaces?.length ?? 0), 0)} معاينة</span></div>
                {businesses.data.some(b => (b.demo_workspaces?.length ?? 0) > 0) ? <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{businesses.data.flatMap(b => (b.demo_workspaces ?? []).map(workspace => ({ business: b, workspace }))).map(({ business: b, workspace }) => <article key={workspace.id} className="rounded-xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-2"><div><h3 className="font-black">{b.name}</h3><p className="mt-1 text-xs text-slate-500">{b.city} · معاينة #{workspace.id}</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${workspace.is_usable ? 'bg-emerald-50 text-emerald-800' : workspace.status === 'revoked' ? 'bg-rose-50 text-rose-800' : 'bg-slate-100 text-slate-600'}`}>{workspace.is_usable ? 'فعّالة' : workspace.status === 'revoked' ? 'متوقفة' : 'منتهية'}</span></div><p className="mt-3 text-xs text-slate-500">إنشاء: {formatDate(workspace.created_at)}</p><p className="mt-1 text-xs text-slate-500">انتهاء: {formatDate(workspace.expires_at)}</p>{workspace.is_usable && <button disabled={revokingWorkspaceId === workspace.id} onClick={() => revokeWorkspace(workspace.id)} className="mt-3 w-full rounded-lg border border-rose-200 px-3 py-2 text-sm font-bold text-rose-700 disabled:opacity-40">{revokingWorkspaceId === workspace.id ? 'جاري الإيقاف...' : 'إيقاف روابط المعاينة'}</button>}</article>)}</div> : <p className="mt-4 rounded-xl bg-slate-50 p-5 text-sm text-slate-500">لسه مفيش معاينات محفوظة للعملاء الظاهرين في الصفحة دي. أنشئ أول Demo من القسم السابق.</p>}
                <div className="mt-6 border-t border-slate-100 pt-5"><h3 className="font-black">روابط اختيار التجربة وحالة الطلب</h3><p className="mt-1 text-sm text-slate-500">كل طلب مرتبط بسجل المطعم. بعد وصول الطلب، جهّز Demo منه مباشرة؛ اختيارات العميل ستنتقل تلقائيًا إلى مساحة التجربة، والروابط السرية لا تُخزن كنص.</p>{businesses.data.some(b => (b.demo_invitations?.length ?? 0) > 0) ? <div className="mt-4 grid gap-3 md:grid-cols-2 xl:grid-cols-3">{businesses.data.flatMap(b => (b.demo_invitations ?? []).map(invitation => ({ business: b, invitation }))).map(({ business: b, invitation }) => <article key={invitation.id} className="rounded-xl border border-slate-200 p-4"><div className="flex items-start justify-between gap-2"><div><h4 className="font-black">{b.name}</h4><p className="mt-1 text-xs text-slate-500">{b.city} · طلب اختيار #{invitation.id}</p></div><span className={`rounded-full px-2.5 py-1 text-[11px] font-bold ${invitation.status === 'requested' ? 'bg-emerald-50 text-emerald-800' : invitation.status === 'demo_ready' ? 'bg-indigo-50 text-indigo-800' : invitation.status === 'revoked' ? 'bg-rose-50 text-rose-800' : 'bg-slate-100 text-slate-700'}`}>{invitation.status === 'requested' ? 'طلب وصل' : invitation.status === 'demo_ready' ? 'Demo جاهز' : invitation.status === 'revoked' ? 'متوقف' : new Date(invitation.expires_at) < new Date() ? 'منتهي' : 'بانتظار اختيار العميل'}</span></div><p className="mt-2 text-xs text-slate-500">إنشاء: {formatDate(invitation.created_at)} · انتهاء: {formatDate(invitation.expires_at)}</p>{invitation.submitted_at && <p className="mt-1 text-xs text-emerald-800">وصل الطلب: {formatDate(invitation.submitted_at)}</p>}{invitation.requested_mode && <p className="mt-2 text-sm">الاختيار: {{ customer_preview: 'تجربة العميل', owner_dashboard: 'لوحة صاحب المطعم', custom_preview: 'معاينة مخصصة' }[invitation.requested_mode] || invitation.requested_mode} · النمط: {invitation.style}</p>}{invitation.demo_workspace_id && <p className="mt-2 text-sm font-bold text-indigo-800">مرتبط بمساحة Demo #{invitation.demo_workspace_id}</p>}{invitation.status === 'requested' && !invitation.demo_workspace_id && <button type="button" disabled={demoBusy} onClick={() => provisionDemoForInvitation(b, invitation.id)} className="mt-3 w-full rounded-lg bg-emerald-800 px-3 py-2 text-sm font-bold text-white disabled:opacity-40">{demoBusy ? 'جاري التجهيز...' : 'تجهيز Demo لهذا الطلب'}</button>}{invitation.status === 'invited' && new Date(invitation.expires_at) > new Date() && <button type="button" onClick={() => revokeInvitation(invitation.id)} className="mt-3 w-full rounded-lg border border-rose-200 px-3 py-2 text-sm font-bold text-rose-700">إيقاف رابط الاختيار</button>}</article>)}</div> : <p className="mt-3 rounded-xl bg-slate-50 p-4 text-sm text-slate-500">لسه مفيش روابط اختيار مرتبطة بالسجلات الظاهرة.</p>}</div>
            </section>
            <section className="mt-5 grid gap-5 xl:grid-cols-2">
                <article className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-black">سجل النشاط الأخير</h2><p className="mt-1 text-sm text-slate-500">تواصل المبيعات، تغييرات حالة الطلب، وتحديثات الدفع عبر المطاعم المرتبطة.</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{recentActivities.length} نشاط</span></div>
                    <div className="mt-4 max-h-[34rem] space-y-3 overflow-y-auto">{recentActivities.length === 0 ? <p className="rounded-xl bg-slate-50 p-5 text-sm text-slate-500">لا يوجد نشاط مسجل بعد. سيظهر هنا سجل التواصل وتغييرات الطلبات والدفع بعد ربط المطعم وتسجيل الأحداث.</p> : recentActivities.map(activity => <div key={activity.id} className="rounded-xl border border-slate-100 p-3"><div className="flex flex-wrap items-center justify-between gap-2"><p className="font-bold">{activity.business_name} <span className="font-normal text-slate-500">· {activity.city || 'مدينة غير محددة'}</span></p><time className="text-xs text-slate-500">{formatDate(activity.occurred_at)}</time></div><div className="mt-2 flex flex-wrap gap-2 text-xs"><span className="rounded-full bg-indigo-50 px-3 py-1 font-bold text-indigo-800">{activityLabels[activity.type] || activity.type}</span>{activity.outcome && <span className="rounded-full bg-emerald-50 px-3 py-1 text-emerald-800">{outcomeLabels[activity.outcome] || activity.outcome}</span>}{activity.channel && <span className="rounded-full bg-slate-100 px-3 py-1">{contactLabels[activity.channel] || (activity.channel === 'qr_menu' ? 'منيو QR' : activity.channel === 'pos' ? 'نظام الكاشير' : activity.channel)}</span>}</div>{activity.notes && <p className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-700">{activity.notes}</p>}<p className="mt-2 text-xs text-slate-400">{activity.actor ? `بواسطة ${activity.actor}` : 'تم تسجيله آليًا'}</p></div>)}</div>
                </article>
                <article className="rounded-2xl border border-slate-200 bg-white p-5"><div className="flex items-start justify-between gap-3"><div><h2 className="text-lg font-black">طلبات المطاعم المرتبطة</h2><p className="mt-1 text-sm text-slate-500">الحالة التشغيلية والدفع وآخر انتقالات الحالة لكل طلب.</p></div><span className="rounded-full bg-slate-100 px-3 py-1 text-xs font-bold">{recentOrders.length} طلب</span></div>
                    <div className="mt-4 max-h-[34rem] space-y-3 overflow-y-auto">{recentOrders.length === 0 ? <p className="rounded-xl bg-slate-50 p-5 text-sm text-slate-500">مفيش طلبات معروضة بعد. اربط سجل المطعم بنظام الطلبات من خلال restaurant_id عشان تظهر بياناته هنا.</p> : recentOrders.map(order => <details key={order.id} className="rounded-xl border border-slate-100 p-3"><summary className="cursor-pointer list-none"><div className="flex flex-wrap items-start justify-between gap-2"><div><p className="font-black">{order.order_number}</p><p className="mt-1 text-sm text-slate-600">{order.restaurant_name} · {order.customer_name}</p><p className="mt-1 text-xs text-slate-400">{formatDate(order.created_at)}</p></div><div className="text-left"><p className="font-black">{formatMoney(order.total)}</p><p className="mt-1 text-xs text-slate-600">{orderStatusLabels[order.status] || order.status} · {paymentStatusLabels[order.payment_status] || order.payment_status}</p></div></div></summary><div className="mt-3 border-t border-slate-100 pt-3"><p className="mb-2 text-xs font-black text-slate-500">تاريخ تغييرات الحالة</p>{order.history.length === 0 ? <p className="text-sm text-slate-500">لا توجد انتقالات مسجلة.</p> : <div className="space-y-2">{order.history.map((event, index) => <div key={`${event.to_status}-${event.created_at || index}`} className="flex flex-wrap justify-between gap-2 text-sm"><span>{event.from_status ? `من ${orderStatusLabels[event.from_status] || event.from_status} إلى ` : 'إنشاء الطلب: '}{orderStatusLabels[event.to_status] || event.to_status}{event.actor ? ` · ${event.actor}` : ''}</span><time className="text-xs text-slate-400">{formatDate(event.created_at)}</time></div>)}</div>}<p className="mt-3 text-xs text-slate-500">تحديثات الدفع تظهر أيضًا في سجل النشاط المجاور.</p></div></details>)}</div>
                </article>
            </section>
            <section className="mt-5 rounded-2xl border border-slate-200 bg-white p-5"><div className="flex flex-col justify-between gap-3 sm:flex-row sm:items-center"><div><h2 className="text-lg font-black">مصادر البيانات</h2><p className="mt-1 text-sm text-slate-600">{provider.name}: {provider.configured ? 'مفتاح موجود — لا يتم تنفيذ بحث تلقائي أو طلب مدفوع في هذه النسخة.' : 'غير مربوط بعد. لا توجد اتصالات خارجية أو تكلفة API.'}</p></div><button onClick={() => setShowForm(v => !v)} className="rounded-xl bg-emerald-700 px-4 py-3 font-bold text-white">{showForm ? 'إغلاق النموذج' : '+ إضافة مطعم مكتشف'}</button></div>
                <p className="mt-3 text-xs leading-6 text-slate-500">الإضافة اليدوية متاحة الآن لتجهيز سير العمل. ربط Google Places API يحتاج إعدادًا منفصلًا وموافقة صريحة على الفوترة والشروط؛ وجود مفتاح وحده لن يشغّل أي طلب.</p>
                <form onSubmit={async e => { e.preventDefault(); if (!provider.enabled || discovering) return; setDiscovering(true); setDiscoverMessage('جاري البحث...'); setDiscoveredPlaces([]); try { const csrf = document.querySelector<HTMLMetaElement>('meta[name="csrf-token"]')?.content; const response = await fetch('/local-scout/discover', { method: 'POST', credentials: 'same-origin', headers: { 'Content-Type': 'application/json', Accept: 'application/json', ...(csrf ? { 'X-CSRF-TOKEN': csrf } : {}) }, body: JSON.stringify({ query: discoverQuery, city: discoverCity }) }); const result = await response.json(); if (!response.ok) throw new Error(result.message || 'تعذر إكمال البحث'); setDiscoveredPlaces(result.places || []); setDiscoverMessage(`نتائج البحث: ${result.found}. ${result.message || ''}`); } catch (error) { setDiscoverMessage(error instanceof Error ? error.message : 'حدث خطأ أثناء البحث'); } finally { setDiscovering(false); } }} className="mt-4 grid gap-3 sm:grid-cols-[1fr_180px_auto]">
                    <input value={discoverQuery} onChange={e => setDiscoverQuery(e.target.value)} maxLength={120} className="rounded-xl border border-slate-200 px-3 py-3" aria-label="عبارة البحث عن المطاعم" />
                    <select value={discoverCity} onChange={e => setDiscoverCity(e.target.value)} className="rounded-xl border border-slate-200 px-3 py-3"><option>الزرقا</option><option>دمياط</option></select>
                    <button disabled={!provider.enabled || discovering || !discoverQuery.trim()} className="rounded-xl bg-slate-950 px-4 py-3 font-bold text-white disabled:cursor-not-allowed disabled:opacity-40">{discovering ? 'جاري البحث...' : 'اكتشاف عبر Google'}</button>
                </form>
                {discoverMessage && <p role="status" className="mt-3 rounded-xl bg-slate-50 p-3 text-sm">{discoverMessage}</p>}
                {discoveredPlaces.length > 0 && <div className="mt-4 rounded-xl border border-slate-200 p-4"><div className="flex items-center justify-between gap-3"><h3 className="font-black">معاينة النتائج — {discoveredPlaces.length}</h3><span className="text-xs font-bold text-slate-500">Google Maps</span></div><p className="mt-1 text-xs leading-5 text-slate-500">المعلومات أدناه من Google Maps للمعاينة فقط، ولا تُحفظ تلقائيًا. راجع صفحة المطعم الرسمية قبل إضافته إلى الدليل.</p><div className="mt-3 space-y-3">{discoveredPlaces.map(place => <article key={place.source_place_id} className="rounded-xl bg-slate-50 p-3"><div className="flex flex-col justify-between gap-2 sm:flex-row"><div><h4 className="font-bold">{place.name}</h4><p className="mt-1 text-sm text-slate-600">{place.address || 'العنوان غير متاح'}</p><p className="mt-1 text-xs text-slate-500">{place.category || 'تصنيف غير محدد'}{place.phone ? ` · ${place.phone}` : ''}</p></div><div className="flex flex-wrap items-start gap-2">{place.maps_url && <a href={place.maps_url} target="_blank" rel="noreferrer" className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold">افتح في Google Maps</a>}{place.website_url && <a href={place.website_url} target="_blank" rel="noreferrer" className="rounded-lg border border-slate-200 bg-white px-3 py-2 text-xs font-bold">الموقع الرسمي</a>}</div></div></article>)}</div></div>}
                {discoveredPlaces.some(place => Boolean(place.website_url)) && <div className="mt-4 rounded-xl border border-indigo-200 bg-indigo-50/50 p-4"><h3 className="font-black">تحويل نتيجة إلى Lead بعد التحقق</h3><p className="mt-1 text-sm leading-6 text-slate-600">افتح الموقع الرسمي من النتائج أعلاه. لما تتأكد إنه للمطعم الصحيح، اضغط الاعتماد. هنستخرج اسم الموقع ونحفظ Google Place ID فقط من بيانات Google، ثم نكتشف روابط المنيو من الموقع الرسمي. لن نحفظ اسم Google أو عنوانه أو هاتفه.</p><div className="mt-3 space-y-2">{discoveredPlaces.filter(place => Boolean(place.website_url)).map(place => <div key={place.source_place_id} className="flex flex-col justify-between gap-2 rounded-lg bg-white p-3 sm:flex-row sm:items-center"><div className="min-w-0"><p className="font-bold">{place.name}</p><p className="break-all text-xs text-slate-500">{place.website_url}</p></div><button type="button" onClick={() => intakeDiscoveredPlace(place)} disabled={intakingPlaceId !== null} className="shrink-0 rounded-lg bg-indigo-700 px-4 py-2 text-sm font-bold text-white disabled:opacity-40">{intakingPlaceId === place.source_place_id ? 'جاري الفحص...' : 'اعتماد الموقع وتجهيز Lead'}</button></div>)}</div></div>}
            </section>
            {showForm && <section className="mt-5 rounded-2xl border border-emerald-200 bg-white p-5"><h2 className="text-lg font-black">إضافة سجل مطعم</h2><Form action="/local-scout/businesses" method="post" className="mt-4 grid gap-3 sm:grid-cols-2 lg:grid-cols-3" onSuccess={() => setShowForm(false)}>{({ processing, errors }) => <>
                <label className="text-sm font-bold">اسم المطعم<input name="name" required maxLength={180} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="اسم المطعم" />{errors.name && <small className="text-red-600">{errors.name}</small>}</label>
                <label className="text-sm font-bold">المدينة<select name="city" required defaultValue="الزرقا" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal"><option>الزرقا</option><option>دمياط</option></select></label>
                <label className="text-sm font-bold">المنطقة<input name="area" maxLength={120} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="مثال: وسط البلد" /></label>
                <label className="text-sm font-bold">التصنيف<input name="category" required defaultValue="مطعم" maxLength={100} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" /></label>
                <label className="text-sm font-bold">رقم الهاتف<input name="phone" maxLength={40} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" /></label>
                <label className="text-sm font-bold">العنوان<input name="address" maxLength={500} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" /></label>
                <label className="text-sm font-bold">رابط الموقع الرسمي<input name="website_url" type="url" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="https://" /></label>
                <label className="text-sm font-bold">رابط الخريطة<input name="maps_url" type="url" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="https://" /></label>
                <label className="text-sm font-bold">رابط مصدر البيانات<input name="source_url" type="url" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="صفحة رسمية أو مصدر مسموح" /></label>
                <label className="text-sm font-bold">رابط المنيو<input name="menu_url" type="url" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="https://" /></label>
                <label className="text-sm font-bold">حالة المنيو<select name="menu_status" defaultValue="unknown" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal"><option value="unknown">غير معروف</option><option value="available">المنيو موجود</option><option value="missing">محتاجين المنيو</option><option value="needs_review">محتاج مراجعة</option></select></label>
                <label className="text-sm font-bold">مرحلة العميل<select name="lead_status" defaultValue="needs_verification" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal">{Object.entries(leadLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label>
                <label className="text-sm font-bold">درجة الثقة (0–100)<input name="confidence_score" type="number" min={0} max={100} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" placeholder="مثال: 80" /></label>
                <label className="text-sm font-bold">قناة التواصل<select name="contact_channel" defaultValue="" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal"><option value="">لم تُحدد</option>{Object.entries(contactLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select></label>
                <label className="text-sm font-bold">حالة حقوق المنيو<select name="menu_rights_status" defaultValue="not_checked" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal"><option value="not_checked">لم يتم التحقق</option><option value="permission_requested">تم طلب الإذن</option><option value="permission_granted">تم منح الإذن</option><option value="licensed">مرخّص</option><option value="not_allowed">غير مسموح</option></select></label>
                <label className="text-sm font-bold">موعد المتابعة القادمة<input name="next_action_at" type="datetime-local" className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" /></label>
                <label className="text-sm font-bold sm:col-span-2 lg:col-span-3">دليل وملاحظات التحقق<textarea name="evidence_notes" maxLength={3000} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" rows={2} placeholder="اكتب ما تم التأكد منه ورابط/تاريخ المصدر، بدون تخمين." /></label>
                <label className="text-sm font-bold sm:col-span-2 lg:col-span-3">ملاحظات داخلية<textarea name="internal_notes" maxLength={3000} className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-3 font-normal" rows={2} /></label>
                <div className="sm:col-span-2 lg:col-span-3"><button disabled={processing} className="rounded-xl bg-slate-950 px-5 py-3 font-bold text-white disabled:opacity-50">حفظ في قاعدة البيانات</button></div>
            </>}</Form></section>}
            <section className="mt-5 rounded-2xl border border-slate-200 bg-white p-5"><form onSubmit={e => { e.preventDefault(); router.get('/local-scout', { q, city, menu_status: menuStatus, lead_status: leadStatus }, { preserveState: true }); }} className="grid gap-3 sm:grid-cols-2 lg:grid-cols-5"><input value={q} onChange={e => setQ(e.target.value)} placeholder="بحث بالاسم أو العنوان أو الهاتف" className="rounded-xl border border-slate-200 px-3 py-3 lg:col-span-2"/><select value={city} onChange={e => setCity(e.target.value)} className="rounded-xl border border-slate-200 px-3 py-3"><option value="">كل المدن</option><option>الزرقا</option><option>دمياط</option></select><select value={menuStatus} onChange={e => setMenuStatus(e.target.value)} className="rounded-xl border border-slate-200 px-3 py-3"><option value="">كل حالات المنيو</option>{Object.entries(menuLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><select value={leadStatus} onChange={e => setLeadStatus(e.target.value)} className="rounded-xl border border-slate-200 px-3 py-3"><option value="">كل مراحل العميل</option>{Object.entries(leadLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select><button className="rounded-xl bg-slate-950 px-4 py-3 font-bold text-white lg:col-span-5">تصفية النتائج</button></form>
                <div className="mt-5 space-y-3">{businesses.data.length === 0 ? <div className="rounded-xl bg-slate-50 p-8 text-center text-slate-500">لسه مفيش سجلات. ابدأ بإضافة أول مجموعة مطاعم للزرقا ودمياط.</div> : businesses.data.map(b => <article key={b.id} className="rounded-2xl border border-slate-200 p-4"><div className="flex flex-col justify-between gap-3 lg:flex-row lg:items-start"><div className="min-w-0 flex-1"><h3 className="font-black">{b.name}</h3><p className="mt-1 text-sm text-slate-500">{[b.city, b.area, b.category, b.phone].filter(Boolean).join(' · ')}</p><div className="mt-2 flex flex-wrap gap-2 text-xs"><span className="rounded-full bg-amber-50 px-3 py-1 text-amber-800">{menuLabels[b.menu_status] || b.menu_status}</span><span className="rounded-full bg-slate-100 px-3 py-1">{listingLabels[b.listing_status] || b.listing_status}</span><span className="rounded-full bg-indigo-50 px-3 py-1 text-indigo-800">{leadLabels[b.lead_status] || b.lead_status}</span><span className="rounded-full bg-slate-100 px-3 py-1">الثقة: {b.confidence_score == null ? 'غير محددة' : `${b.confidence_score}%`}</span><span className="rounded-full bg-slate-100 px-3 py-1">{b.claim_status === 'verified' ? 'تم التحقق من المالك' : b.claim_status === 'contacted' ? 'تم التواصل' : b.claim_status === 'claimed' ? 'طلب إدارة الصفحة' : 'غير مطالب بها'}</span><span className="rounded-full bg-slate-100 px-3 py-1">حقوق المنيو: {b.menu_rights_status === 'permission_granted' ? 'الإذن موجود' : b.menu_rights_status === 'licensed' ? 'مرخّص' : b.menu_rights_status === 'permission_requested' ? 'الإذن مطلوب' : b.menu_rights_status === 'not_allowed' ? 'غير مسموح' : 'لم يتم التحقق'}</span></div>{b.restaurant_id && b.order_stats ? <div className="mt-4 grid gap-2 rounded-xl bg-slate-50 p-3 sm:grid-cols-2 xl:grid-cols-4"><div><p className="text-xs text-slate-500">إجمالي الطلبات</p><p className="mt-1 font-black">{b.order_stats.orders_count}</p></div><div><p className="text-xs text-slate-500">طلبات مكتملة</p><p className="mt-1 font-black">{b.order_stats.completed_orders}</p></div><div><p className="text-xs text-slate-500">طلبات مفتوحة</p><p className="mt-1 font-black">{b.order_stats.open_orders}</p></div><div><p className="text-xs text-slate-500">قيمة مدفوعات مسجلة</p><p className="mt-1 font-black">{formatMoney(b.order_stats.paid_revenue)}</p></div></div> : <p className="mt-3 rounded-lg bg-slate-50 p-3 text-xs text-slate-500">لم يتم ربط سجل هذا المطعم بنظام الطلبات بعد؛ بيانات المبيعات ستظهر بعد الربط.</p>}{b.evidence_notes && <p className="mt-3 whitespace-pre-wrap text-sm leading-6 text-slate-700">دليل التحقق: {b.evidence_notes}</p>}{b.last_contacted_at && <p className="mt-2 text-xs text-slate-500">آخر تواصل: {formatDate(b.last_contacted_at)}</p>}{b.next_action_at && <p className="mt-1 text-xs text-slate-500">المتابعة القادمة: {formatDate(b.next_action_at)}</p>}</div><div className="flex flex-wrap gap-2 lg:max-w-xs"><button onClick={async () => { try { await navigator.clipboard.writeText(firstContactMessage(b)); window.alert('اتنسخت رسالة التواصل. لم يتم إرسالها أو تغيير حالة العميل.'); } catch { window.alert('تعذر النسخ تلقائيًا. راجع ملف NEXORA_DEMO_AND_OUTREACH_SYSTEM.md لنسخة الرسالة.'); } }} className="rounded-lg border border-emerald-300 bg-emerald-50 px-3 py-2 text-sm font-bold text-emerald-900">نسخ رسالة مخصصة</button><select aria-label={`مرحلة العميل: ${b.name}`} value={b.lead_status || 'needs_verification'} onChange={e => router.patch(`/local-scout/businesses/${b.id}`, { lead_status: e.target.value })} className="rounded-lg border border-slate-200 px-3 py-2 text-sm">{Object.entries(leadLabels).map(([key, label]) => <option key={key} value={key}>{label}</option>)}</select>{b.source_url && <a href={b.source_url} target="_blank" rel="noreferrer" className="rounded-lg border border-slate-200 px-3 py-2 text-sm">المصدر</a>}<button onClick={() => { const next = b.listing_status === 'published' ? 'draft' : 'published'; if (next === 'published' && !b.source_url) { window.alert('أضف رابط مصدر موثوق أولًا من قاعدة البيانات.'); return; } router.patch(`/local-scout/businesses/${b.id}`, { listing_status: next }); }} className="rounded-lg bg-slate-950 px-3 py-2 text-sm font-bold text-white">{b.listing_status === 'published' ? 'إلغاء النشر' : 'نشر في الدليل'}</button><button onClick={() => router.patch(`/local-scout/businesses/${b.id}`, { menu_status: b.menu_status === 'available' ? 'needs_review' : 'available' })} className="rounded-lg border border-slate-200 px-3 py-2 text-sm">{b.menu_status === 'available' ? 'مراجعة المنيو' : 'تأكيد وجود المنيو'}</button></div></div></article>)}</div>
                <nav className="mt-5 flex flex-wrap gap-2">{businesses.links.map((link, i) => <button key={`${link.label}-${i}`} disabled={!link.url} onClick={() => link.url && router.visit(link.url)} className={`rounded-lg border px-3 py-2 text-sm ${link.active ? 'bg-slate-950 text-white' : 'bg-white'} disabled:opacity-40`} dangerouslySetInnerHTML={{ __html: link.label }} />)}</nav>
            </section>
        </div></main>;
}
